import { SceneEvents, State } from "../../../../common";
import type { Observable } from "../../../../common";
import {
  cinderella2048Config,
  Cinderella2048Direction,
  Cinderella2048GridModel,
  storageGet,
  storageSet,
} from "./model";
import type { ICinderella2048GridSnapshot, ICinderella2048MergeEvent } from "./model";
import type { ICinderella2048GameEffectPayload, ICinderella2048GameEvents } from "./events";
import { Cinderella2048BoardView } from "./components/Cinderella2048BoardView";
import { Cinderella2048InputController } from "./components/Cinderella2048InputController";
import { resolveCinderella2048Stage } from "./components/resolveStage";
import type { Cinderella2048GameStatus, ICinderella2048GameProps, ICinderella2048GameState } from "./types";

interface ISpawnCinderella2048MergeEffectsAfterSlideProps {
  mergeEvents: ICinderella2048MergeEvent[];
  animationVersion: number;
}

interface ISpawnCinderella2048NewTileEffectsAfterSlideProps {
  row: number;
  col: number;
  value: number;
  animationVersion: number;
}

/** Управляет моделью, полем, вводом и публичным состоянием игры 2048. */
export class Cinderella2048Game {
  private grid: Cinderella2048GridModel;
  private history: ICinderella2048GridSnapshot[];
  private status: Cinderella2048GameStatus;
  private bestScore: number;
  private maxReachedTile: number;
  private state: State<ICinderella2048GameState>;
  private boardView: Cinderella2048BoardView;
  private inputController: Cinderella2048InputController;
  private sceneEvents: SceneEvents<ICinderella2048GameEvents>;
  private animationVersion: number;
  private inputBlockedUntil: number;

  /** Создает игровой компонент в указанной сцене. */
  constructor(private props: ICinderella2048GameProps) {
    this.grid = new Cinderella2048GridModel(cinderella2048Config.gridSize);
    this.history = [];
    this.status = "playing";
    this.bestScore = Number(storageGet(cinderella2048Config.storageBestScoreKey, "0")) || 0;
    this.maxReachedTile = this.grid.getMaxValue();
    this.state = new State<ICinderella2048GameState>(this.createState());
    this.sceneEvents = new SceneEvents<ICinderella2048GameEvents>({ scene: props.scene });
    this.animationVersion = 0;
    this.inputBlockedUntil = 0;
    this.boardView = new Cinderella2048BoardView({ scene: props.scene, spriteConfig: props.spriteConfig });
    this.inputController = new Cinderella2048InputController({
      scene: props.scene,
      boardView: this.boardView,
      onMove: (direction) => this.handleMove(direction),
      onRestart: () => this.reset(),
    });

    this.subscribeToSceneEvents();
    this.publishMaxTile();
  }

  /** Уничтожает все компоненты игрового вида. */
  destroy(): void {
    this.animationVersion += 1;
    this.inputBlockedUntil = 0;
    this.inputController.destroy();
    this.sceneEvents.unSubscribeAll();
    this.state.unSubScribeAll();
    this.boardView.destroy();
  }

  /** Возвращает наблюдаемое состояние для UI и менеджеров сцены. */
  getState(): Observable<ICinderella2048GameState> {
    return this.state;
  }

  /** Обновляет анимации поля. */
  update(time: number): void {
    this.boardView.update(this.grid, time);
  }

  /** Сбрасывает игру к начальному состоянию. */
  reset(): void {
    this.animationVersion += 1;
    this.inputBlockedUntil = 0;
    this.boardView.clearMergeAnimations();
    this.boardView.clearTileRevealDelays();
    this.grid.reset();
    this.history = [];
    this.status = "playing";
    this.maxReachedTile = this.grid.getMaxValue();
    this.sceneEvents.emit("cinderella2048ClearParticles");
    this.publishMaxTile();
    this.publishState();
  }

  /** Выполняет ход игрока. */
  private handleMove(direction: Cinderella2048Direction): void {
    if (this.isMoveBlocked()) {
      return;
    }

    const snapshot = this.grid.createSnapshot();
    this.saveSnapshot(snapshot);

    const result = this.grid.move(direction);

    if (!result.moved) {
      this.history.pop();
      return;
    }

    /** Отмечаем каждый успешный ход отдельной версией, чтобы опоздавшие delayedCall прошлого хода не сработали поверх новой модели. */
    this.animationVersion += 1;
    const animationVersion = this.animationVersion;
    const revealAt = window.performance.now() + cinderella2048Config.timings.moveMs;

    this.inputBlockedUntil = revealAt;
    this.sceneEvents.emit("tilesMove");
    this.boardView.playMergeAnimations(result.animation.merges);
    this.spawnMergeEffectsAfterSlide({ mergeEvents: result.mergeEvents, animationVersion });

    const newTile = this.grid.addRandomTile();

    if (newTile) {
      this.boardView.delayTileReveal({ tileId: newTile.id, revealAt });
      this.spawnNewTileEffectsAfterSlide({
        row: newTile.row,
        col: newTile.col,
        value: newTile.value,
        animationVersion,
      });
    }

    this.updateBestScore();
    this.updateMaxReachedTile();
    this.evaluateGameState(animationVersion);
    this.publishState();
  }

  /** Проверяет, заблокирован ли сейчас ввод ходов. */
  private isMoveBlocked(): boolean {
    return this.status !== "playing" || this.grid.over || window.performance.now() < this.inputBlockedUntil;
  }

  /** Подписывает игру на команды UI и диалогов сцены. */
  private subscribeToSceneEvents(): void {
    this.sceneEvents.on("cinderella2048NewGameRequest", () => this.reset());
    this.sceneEvents.on("cinderella2048UndoRequest", () => this.undo());
    this.sceneEvents.on("cinderella2048ContinueRequest", () => this.continueAfterWin());
  }

  /** Сохраняет снимок в историю отмены. */
  private saveSnapshot(snapshot: ICinderella2048GridSnapshot): void {
    this.history.push(snapshot);

    if (this.history.length > cinderella2048Config.maxHistory) {
      this.history.shift();
    }
  }

  /** Отменяет последний успешный ход. */
  private undo(): void {
    const snapshot = this.history.pop();

    if (!snapshot) {
      return;
    }

    this.grid.restoreSnapshot(snapshot);
    this.animationVersion += 1;
    this.inputBlockedUntil = 0;
    this.boardView.clearMergeAnimations();
    this.boardView.clearTileRevealDelays();
    this.grid.over = false;
    this.status = "playing";
    this.sceneEvents.emit("cinderella2048ClearParticles");
    this.publishState();
  }

  /** Продолжает игру после победного диалога. */
  private continueAfterWin(): void {
    if (this.status !== "win") {
      return;
    }

    this.status = "playing";
    this.publishState();
  }

  /** Обновляет рекорд и сохраняет его в localStorage. */
  private updateBestScore(): void {
    if (this.grid.score <= this.bestScore) {
      return;
    }

    this.bestScore = this.grid.score;
    storageSet(cinderella2048Config.storageBestScoreKey, String(this.bestScore));
  }

  /** Обновляет максимальную достигнутую плитку текущей партии и сообщает сцене о новом этапе. */
  private updateMaxReachedTile(): void {
    const maxTile = this.grid.getMaxValue();

    if (maxTile <= this.maxReachedTile) {
      return;
    }

    this.maxReachedTile = maxTile;
    this.publishMaxTile();
  }

  /** Проверяет победу и конец игры после хода. */
  private evaluateGameState(animationVersion: number): void {
    if (!this.grid.won && this.grid.getMaxValue() >= cinderella2048Config.winValue) {
      this.grid.won = true;
      this.status = "win";
      this.spawnVictoryEffectsAfterSlide(animationVersion);
      return;
    }

    if (!this.grid.canMove()) {
      this.grid.over = true;
      this.status = "game-over";
    }
  }

  /** Создает частицы для всех слияний текущего хода через события сцены. */
  private spawnMergeEffects(mergeEvents: ICinderella2048MergeEvent[]): void {
    for (const event of mergeEvents) {
      const center = this.boardView.getCellCenter(event.row, event.col);

      this.sceneEvents.emit("cinderella2048MergeParticles", this.createEffectPayload(center, event.value, event.sourceValue));
    }
  }

  /** Запускает частицы слияния после того, как исходная плитка доехала до целевой. */
  private spawnMergeEffectsAfterSlide(props: ISpawnCinderella2048MergeEffectsAfterSlideProps): void {
    if (props.mergeEvents.length === 0) {
      return;
    }

    const { scene } = this.props;

    scene.time.delayedCall(cinderella2048Config.timings.moveMs, () => {
      if (props.animationVersion !== this.animationVersion) {
        return;
      }

      this.spawnMergeEffects(props.mergeEvents);
    });
  }

  /** Запускает частицы появления новой плитки после окончания slide-фазы хода. */
  private spawnNewTileEffectsAfterSlide(props: ISpawnCinderella2048NewTileEffectsAfterSlideProps): void {
    const { scene } = this.props;

    scene.time.delayedCall(cinderella2048Config.timings.moveMs, () => {
      if (props.animationVersion !== this.animationVersion) {
        return;
      }

      const center = this.boardView.getCellCenter(props.row, props.col);
      this.sceneEvents.emit("cinderella2048NewTileParticles", this.createEffectPayload(center, props.value));
    });
  }

  /** Создает праздничный эффект при достижении плитки 2048. */
  private spawnVictoryEffects(): void {
    const center = this.boardView.getBoardCenter();

    this.sceneEvents.emit("cinderella2048VictoryParticles", this.createEffectPayload(center, cinderella2048Config.winValue));
  }

  /** Запускает победные частицы после slide-фазы победного слияния. */
  private spawnVictoryEffectsAfterSlide(animationVersion: number): void {
    const { scene } = this.props;

    scene.time.delayedCall(cinderella2048Config.timings.moveMs, () => {
      if (animationVersion !== this.animationVersion) {
        return;
      }

      this.spawnVictoryEffects();
    });
  }

  /** Создает payload визуального эффекта без раскрытия model-типа наружу. */
  private createEffectPayload(position: { x: number; y: number }, value: number, mergeSourceValue?: number): ICinderella2048GameEffectPayload {
    const stage = resolveCinderella2048Stage(value);

    return {
      x: position.x,
      y: position.y,
      colorLight: stage.colorLight,
      particle: stage.particle,
      value,
      mergeSourceValue,
    };
  }

  /** Публикует текущее состояние игры для внешних компонентов. */
  private publishState(): void {
    this.state.setState(this.createState());
  }

  /** Излучает компактное событие прогресса, чтобы фон не зависел от Observable состояния игры. */
  private publishMaxTile(): void {
    this.sceneEvents.emit("cinderella2048MaxTileChange", { maxTile: this.maxReachedTile });
  }

  /** Создает снимок публичного состояния без доступа к модели. */
  private createState(): ICinderella2048GameState {
    return {
      score: this.grid.score,
      best: Math.max(this.bestScore, this.grid.score),
      moves: this.grid.moves,
      canUndo: this.history.length > 0,
      status: this.status,
    };
  }

}
