import {
  cinderella2048Config,
  Cinderella2048StageConfig,
  Cinderella2048StageValue,
} from "../model";

/** Находит ближайшую поддерживаемую стадию для значения плитки. */
export function resolveCinderella2048StageValue(value: number): Cinderella2048StageValue {
  let resolved = cinderella2048Config.supportedValues[0] as Cinderella2048StageValue;

  for (const stageValue of cinderella2048Config.supportedValues) {
    if (value >= stageValue) {
      resolved = stageValue as Cinderella2048StageValue;
    }
  }

  return resolved;
}

/** Возвращает визуальную конфигурацию стадии плитки. */
export function resolveCinderella2048Stage(value: number): Cinderella2048StageConfig {
  return cinderella2048Config.stagesByValue[resolveCinderella2048StageValue(value)];
}
