import { clamp, randomRange } from "./utils";

export type Cinderella2048ParticleShape = "circle" | "diamond" | "star";

interface ICinderella2048ParticleProps {
  scene: Phaser.Scene;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  life: number;
  color: string;
  shape: Cinderella2048ParticleShape;
}

/** Представляет одну рисованную частицу эффекта. */
export class Cinderella2048Particle extends Phaser.GameObjects.Graphics {
  private vx: number;
  private vy: number;
  private radius: number;
  private life: number;
  private totalLife: number;
  private color: number;
  private shape: Cinderella2048ParticleShape;
  private spin: number;
  private gravity: number;

  /** Создает частицу с физическими параметрами и стилем. */
  constructor(props: ICinderella2048ParticleProps) {
    super(props.scene);

    this.x = props.x;
    this.y = props.y;
    this.vx = props.vx;
    this.vy = props.vy;
    this.radius = props.radius;
    this.life = props.life;
    this.totalLife = props.life;
    this.color = Phaser.Display.Color.HexStringToColor(props.color).color;
    this.shape = props.shape;
    this.rotation = randomRange(0, Math.PI * 2);
    this.spin = randomRange(-5, 5);
    this.gravity = randomRange(10, 70);
    this.draw();
  }

  /** Обновляет положение, прозрачность и оставшееся время жизни. */
  updateParticle(deltaSeconds: number): boolean {
    this.vy += this.gravity * deltaSeconds;
    this.x += this.vx * deltaSeconds;
    this.y += this.vy * deltaSeconds;
    this.rotation += this.spin * deltaSeconds;
    this.life -= deltaSeconds;
    this.setAlpha(clamp(this.life / this.totalLife, 0, 1));
    this.draw();

    return this.life > 0;
  }

  /** Рисует частицу выбранной формы в локальных координатах. */
  private draw(): void {
    this.clear();
    this.fillStyle(this.color, 1);

    if (this.shape === "star") {
      this.drawStar();
    } else if (this.shape === "diamond") {
      this.drawDiamond();
    } else {
      this.fillCircle(0, 0, this.radius);
    }
  }

  /** Рисует ромбовидную частицу. */
  private drawDiamond(): void {
    this.beginPath();
    this.moveTo(0, -this.radius);
    this.lineTo(this.radius, 0);
    this.lineTo(0, this.radius);
    this.lineTo(-this.radius, 0);
    this.closePath();
    this.fillPath();
  }

  /** Рисует пятиконечную искру. */
  private drawStar(): void {
    const points = 10;

    this.beginPath();

    for (let index = 0; index < points; index += 1) {
      const angle = -Math.PI / 2 + index * Math.PI / 5;
      const radius = index % 2 === 0 ? this.radius : this.radius * 0.45;
      const x = Math.cos(angle) * radius;
      const y = Math.sin(angle) * radius;

      if (index === 0) {
        this.moveTo(x, y);
      } else {
        this.lineTo(x, y);
      }
    }

    this.closePath();
    this.fillPath();
  }
}
