import { ICinderella2048TileSnapshot } from "./types";

let nextTileId = 1;

interface ICinderella2048TileModelProps {
  value: number;
  row: number;
  col: number;
}

/** Описывает одну плитку на поле и ее анимационные флаги. */
export class Cinderella2048TileModel {
  id: number;
  value: number;
  row: number;
  col: number;
  fromRow: number;
  fromCol: number;
  createdAt: number;
  moveStartedAt: number;
  mergeStartedAt: number;
  justCreated: boolean;
  justMerged: boolean;
  consumed: boolean;

  /** Создает плитку с указанным значением и позицией. */
  constructor(props: ICinderella2048TileModelProps) {
    this.id = nextTileId;
    nextTileId += 1;

    this.value = props.value;
    this.row = props.row;
    this.col = props.col;
    this.fromRow = props.row;
    this.fromCol = props.col;
    this.createdAt = window.performance.now();
    this.moveStartedAt = this.createdAt;
    this.mergeStartedAt = 0;
    this.justCreated = true;
    this.justMerged = false;
    this.consumed = false;
  }

  /** Создает плитку из сериализованных данных. */
  static fromData(data: ICinderella2048TileSnapshot): Cinderella2048TileModel {
    const tile = new Cinderella2048TileModel({ value: data.value, row: data.row, col: data.col });

    tile.id = data.id;
    tile.fromRow = data.fromRow;
    tile.fromCol = data.fromCol;
    tile.createdAt = data.createdAt;
    tile.moveStartedAt = data.moveStartedAt;
    tile.mergeStartedAt = data.mergeStartedAt;
    tile.justCreated = data.justCreated;
    tile.justMerged = data.justMerged;
    tile.consumed = data.consumed;

    if (tile.id >= nextTileId) {
      nextTileId = tile.id + 1;
    }

    return tile;
  }

  /** Сериализует плитку для истории хода. */
  toData(): ICinderella2048TileSnapshot {
    return {
      id: this.id,
      value: this.value,
      row: this.row,
      col: this.col,
      fromRow: this.fromRow,
      fromCol: this.fromCol,
      createdAt: this.createdAt,
      moveStartedAt: this.moveStartedAt,
      mergeStartedAt: this.mergeStartedAt,
      justCreated: this.justCreated,
      justMerged: this.justMerged,
      consumed: this.consumed,
    };
  }

  /** Запоминает текущую позицию как стартовую точку анимации движения. */
  rememberPreviousPosition(): void {
    this.fromRow = this.row;
    this.fromCol = this.col;
    this.moveStartedAt = window.performance.now();
  }

  /** Перемещает плитку в новую клетку. */
  setPosition(row: number, col: number): void {
    this.row = row;
    this.col = col;
  }

  /** Отмечает плитку как результат слияния. */
  markMerged(nextValue: number): void {
    this.value = nextValue;
    this.justMerged = true;
    this.mergeStartedAt = window.performance.now();
  }

  /** Сбрасывает временные флаги перед новым ходом. */
  clearTurnFlags(): void {
    this.justCreated = false;
    this.justMerged = false;
    this.consumed = false;
    this.fromRow = this.row;
    this.fromCol = this.col;
  }
}
