interface IPreloadHtmlImagesProps {
  urls: string[];
}

/** Предварительно загружает и декодирует изображения для последующего CSS/HTML-использования. */
export function preloadHtmlImages(props: IPreloadHtmlImagesProps): Promise<void[]> {
  return Promise.all(props.urls.map((url) => preloadHtmlImage(url)));
}

/** Загружает одно изображение через браузерный Image API без участия Phaser loader progress. */
function preloadHtmlImage(url: string): Promise<void> {
  return new Promise((resolve) => {
    const image = new Image();

    image.onload = () => {
      if (!image.decode) {
        resolve();
        return;
      }

      image.decode().then(() => resolve()).catch(() => resolve());
    };
    image.onerror = () => resolve();
    image.src = url;
  });
}
