import { SceneEvents } from "../../../../common";
import type { ISoundManagerEvents, ISoundManagerEffectPayload } from "./events";
import type { ISoundConfig, ISoundEffectConfig } from "./types";

interface ISoundManagerProps {
  scene: Phaser.Scene;
  soundConfig: ISoundConfig;
}

/** Слушает игровые события сцены и воспроизводит звуки Cinderella 2048. */
export class SoundManager {
  private readonly sceneEvents: SceneEvents<ISoundManagerEvents>;

  /** Создает менеджер звука и подписывает его на уже существующие события сцены. */
  constructor(private readonly props: ISoundManagerProps) {
    this.sceneEvents = new SceneEvents<ISoundManagerEvents>({ scene: props.scene });
    this.sceneEvents.on("tilesMove", () => this.playMoveSound());
    this.sceneEvents.on("cinderella2048MergeParticles", (payload) => this.playMergeSound(payload));
  }

  /** Очищает подписки менеджера звука. */
  destroy(): void {
    this.sceneEvents.unSubscribeAll();
  }

  /** Воспроизводит случайный звук группового движения плиток. */
  private playMoveSound(): void {
    const { soundConfig } = this.props;

    this.playRandomSound(soundConfig.move);
  }

  /** Воспроизводит pop-звук по исходному значению слившихся плиток. */
  private playMergeSound(payload: ISoundManagerEffectPayload): void {
    const { soundConfig } = this.props;
    const tileValue = payload.mergeSourceValue ?? payload.value;
    const soundEffect = soundConfig.mergeByTileValue[tileValue] ?? this.getHighestSound(tileValue);

    if (!soundEffect) {
      return;
    }

    this.playRandomSound(soundEffect);
  }

  /** Возвращает самый высокий настроенный звук для значений выше текущей таблицы. */
  private getHighestSound(tileValue: number): ISoundEffectConfig | undefined {
    const { soundConfig } = this.props;
    const configuredValues = Object
      .keys(soundConfig.mergeByTileValue)
      .map((value) => Number(value))
      .filter((value) => Number.isFinite(value) && value <= tileValue)
      .sort((left, right) => right - left);
    const highestValue = configuredValues[0];

    if (highestValue === undefined) {
      return undefined;
    }

    return soundConfig.mergeByTileValue[highestValue];
  }

  /** Выбирает один звук из массива и проигрывает его через Phaser sound manager. */
  private playRandomSound(soundEffect: ISoundEffectConfig): void {
    const { scene } = this.props;
    const soundName = this.pickRandomSoundName(soundEffect.soundNames);

    if (!soundName) {
      return;
    }

    scene.sound.play(soundName, { volume: soundEffect.volume });
  }

  /** Возвращает случайный asset name из списка звуков. */
  private pickRandomSoundName(soundNames: string[]): string | null {
    if (soundNames.length === 0) {
      return null;
    }

    const index = Math.floor(Math.random() * soundNames.length);

    return soundNames[index] ?? null;
  }
}
