import { cinderella2048Config, cinderella2048Directions } from "./constants";
import { Cinderella2048TileModel } from "./TileModel";
import { createMatrix, pickRandom } from "./utils";
import {
  Cinderella2048Direction,
  Cinderella2048GridSnapshotRows,
  ICinderella2048AnimationTransaction,
  ICinderella2048Cell,
  ICinderella2048GridSnapshot,
  ICinderella2048MergeAnimation,
  ICinderella2048MergeEvent,
  ICinderella2048MoveResult,
} from "./types";

interface IProcessCinderella2048LineProps {
  cells: ICinderella2048Cell[];
  newGrid: Array<Array<Cinderella2048TileModel | null>>;
  mergeEvents: ICinderella2048MergeEvent[];
  mergeAnimations: ICinderella2048MergeAnimation[];
}

/** Управляет квадратной сеткой, правилами 2048 и счетом. */
export class Cinderella2048GridModel {
  size: number;
  grid: Array<Array<Cinderella2048TileModel | null>>;
  score: number;
  moves: number;
  won: boolean;
  over: boolean;

  /** Создает игровое поле указанного размера. */
  constructor(size: number) {
    this.size = size;
    this.grid = this.createEmptyGrid();
    this.score = 0;
    this.moves = 0;
    this.won = false;
    this.over = false;
    this.reset();
  }

  /** Полностью сбрасывает поле и добавляет стартовые плитки. */
  reset(): void {
    this.grid = this.createEmptyGrid();
    this.score = 0;
    this.moves = 0;
    this.won = false;
    this.over = false;

    for (let index = 0; index < cinderella2048Config.startTiles; index += 1) {
      this.addRandomTile();
    }
  }

  /** Проверяет, находится ли клетка внутри поля. */
  isInside(row: number, col: number): boolean {
    return row >= 0 && row < this.size && col >= 0 && col < this.size;
  }

  /** Возвращает плитку в заданной клетке. */
  getTile(row: number, col: number): Cinderella2048TileModel | null {
    if (!this.isInside(row, col)) {
      return null;
    }

    return this.grid[row][col];
  }

  /** Возвращает список всех пустых клеток. */
  getEmptyCells(): ICinderella2048Cell[] {
    const cells: ICinderella2048Cell[] = [];

    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        if (this.grid[row][col] === null) {
          cells.push({ row, col });
        }
      }
    }

    return cells;
  }

  /** Добавляет новую плитку в случайную пустую клетку. */
  addRandomTile(): Cinderella2048TileModel | null {
    const emptyCells = this.getEmptyCells();
    const cell = pickRandom(emptyCells);

    if (!cell) {
      return null;
    }

    const value = Math.random() < cinderella2048Config.newTileChance ? 2 : 4;
    const tile = new Cinderella2048TileModel({ value, row: cell.row, col: cell.col });
    this.grid[cell.row][cell.col] = tile;

    return tile;
  }

  /** Создает сериализованный снимок текущего состояния. */
  createSnapshot(): ICinderella2048GridSnapshot {
    const rows: Cinderella2048GridSnapshotRows = [];

    for (let row = 0; row < this.size; row += 1) {
      rows[row] = [];

      for (let col = 0; col < this.size; col += 1) {
        const tile = this.grid[row][col];
        rows[row][col] = tile ? tile.toData() : null;
      }
    }

    return {
      size: this.size,
      grid: rows,
      score: this.score,
      moves: this.moves,
      won: this.won,
      over: this.over,
    };
  }

  /** Восстанавливает поле из снимка. */
  restoreSnapshot(snapshot: ICinderella2048GridSnapshot): void {
    this.size = snapshot.size;
    this.grid = this.createEmptyGrid();
    this.score = snapshot.score;
    this.moves = snapshot.moves;
    this.won = snapshot.won;
    this.over = snapshot.over;

    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        const tileData = snapshot.grid[row][col];

        if (tileData) {
          this.grid[row][col] = Cinderella2048TileModel.fromData(tileData);
        }
      }
    }
  }

  /** Выполняет ход в выбранном направлении. */
  move(direction: Cinderella2048Direction): ICinderella2048MoveResult {
    const lines = this.getLinesForDirection(direction);
    const newGrid = this.createEmptyGrid();
    const mergeEvents: ICinderella2048MergeEvent[] = [];
    const mergeAnimations: ICinderella2048MergeAnimation[] = [];
    let totalScore = 0;
    let moved = false;
    const animation: ICinderella2048AnimationTransaction = {
      merges: mergeAnimations,
    };

    if (lines.length === 0 || this.over) {
      return { moved: false, scoreGained: 0, mergeEvents, animation };
    }

    this.clearTurnFlags();

    for (const line of lines) {
      const lineResult = this.processLine({
        cells: line,
        newGrid,
        mergeEvents,
        mergeAnimations,
      });
      moved = moved || lineResult.moved;
      totalScore += lineResult.scoreGained;
    }

    if (!moved) {
      return { moved: false, scoreGained: 0, mergeEvents, animation };
    }

    this.grid = newGrid;
    this.score += totalScore;
    this.moves += 1;

    return { moved: true, scoreGained: totalScore, mergeEvents, animation };
  }

  /** Проверяет, есть ли хотя бы один доступный ход. */
  canMove(): boolean {
    return this.getEmptyCells().length > 0 || this.hasEqualNeighbor();
  }

  /** Возвращает максимальное значение на поле. */
  getMaxValue(): number {
    let max = 0;

    this.forEachTile((tile) => {
      if (tile.value > max) {
        max = tile.value;
      }
    });

    return max;
  }

  /** Выполняет функцию для каждой плитки на поле. */
  forEachTile(callback: (tile: Cinderella2048TileModel) => void): void {
    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        const tile = this.grid[row][col];

        if (tile) {
          callback(tile);
        }
      }
    }
  }

  /** Создает пустую матрицу поля. */
  private createEmptyGrid(): Array<Array<Cinderella2048TileModel | null>> {
    return createMatrix<Cinderella2048TileModel | null>(this.size, null);
  }

  /** Сбрасывает временные флаги у всех плиток. */
  private clearTurnFlags(): void {
    this.forEachTile((tile) => tile.clearTurnFlags());
  }

  /** Строит линии обхода поля для заданного направления. */
  private getLinesForDirection(direction: Cinderella2048Direction): ICinderella2048Cell[][] {
    const lines: ICinderella2048Cell[][] = [];

    if (direction === cinderella2048Directions.left) {
      for (let row = 0; row < this.size; row += 1) {
        const line: ICinderella2048Cell[] = [];

        for (let col = 0; col < this.size; col += 1) {
          line.push({ row, col });
        }

        lines.push(line);
      }
    } else if (direction === cinderella2048Directions.right) {
      for (let row = 0; row < this.size; row += 1) {
        const line: ICinderella2048Cell[] = [];

        for (let col = this.size - 1; col >= 0; col -= 1) {
          line.push({ row, col });
        }

        lines.push(line);
      }
    } else if (direction === cinderella2048Directions.up) {
      for (let col = 0; col < this.size; col += 1) {
        const line: ICinderella2048Cell[] = [];

        for (let row = 0; row < this.size; row += 1) {
          line.push({ row, col });
        }

        lines.push(line);
      }
    } else if (direction === cinderella2048Directions.down) {
      for (let col = 0; col < this.size; col += 1) {
        const line: ICinderella2048Cell[] = [];

        for (let row = this.size - 1; row >= 0; row -= 1) {
          line.push({ row, col });
        }

        lines.push(line);
      }
    }

    return lines;
  }

  /** Сжимает и объединяет одну линию поля. */
  private processLine(props: IProcessCinderella2048LineProps): { moved: boolean; scoreGained: number } {
    const tiles = this.collectTilesFromLine(props.cells);
    const placed: Cinderella2048TileModel[] = [];
    let moved = false;
    let scoreGained = 0;

    for (const tile of tiles) {
      tile.rememberPreviousPosition();
      const previous = placed.length > 0 ? placed[placed.length - 1] : null;

      if (previous && previous.value === tile.value && !previous.justMerged) {
        const value = previous.value;
        const nextValue = value * 2;
        const toRow = previous.row;
        const toCol = previous.col;

        tile.setPosition(toRow, toCol);
        previous.markMerged(nextValue);
        tile.consumed = true;
        moved = true;
        scoreGained += nextValue;
        props.mergeEvents.push({ row: toRow, col: toCol, value: nextValue, sourceValue: value });
        props.mergeAnimations.push({
          sourceTileId: tile.id,
          targetTileId: previous.id,
          fromRow: tile.fromRow,
          fromCol: tile.fromCol,
          toRow,
          toCol,
          value,
          nextValue,
          startedAt: tile.moveStartedAt,
        });
      } else {
        const targetCell = props.cells[placed.length];
        tile.setPosition(targetCell.row, targetCell.col);

        if (tile.fromRow !== tile.row || tile.fromCol !== tile.col) {
          moved = true;
        }

        placed.push(tile);
      }
    }

    for (const tile of placed) {
      props.newGrid[tile.row][tile.col] = tile;
    }

    return { moved, scoreGained };
  }

  /** Собирает существующие плитки из линии в порядке движения. */
  private collectTilesFromLine(cells: ICinderella2048Cell[]): Cinderella2048TileModel[] {
    const tiles: Cinderella2048TileModel[] = [];

    for (const cell of cells) {
      const tile = this.grid[cell.row][cell.col];

      if (tile) {
        tiles.push(tile);
      }
    }

    return tiles;
  }

  /** Проверяет наличие соседних плиток с одинаковыми значениями. */
  private hasEqualNeighbor(): boolean {
    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        const tile = this.grid[row][col];

        if (!tile) {
          continue;
        }

        const right = this.getTile(row, col + 1);
        const down = this.getTile(row + 1, col);

        if ((right && right.value === tile.value) || (down && down.value === tile.value)) {
          return true;
        }
      }
    }

    return false;
  }
}
