interface IClampProps {
  value: number;
  min: number;
  max: number;
}

interface ILerpProps {
  start: number;
  end: number;
  progress: number;
}

/** Ограничивает число заданным диапазоном. */
export function clamp(props: IClampProps): number {
  return Math.max(props.min, Math.min(props.max, props.value));
}

/** Выполняет линейную интерполяцию между двумя числами. */
export function lerp(props: ILerpProps): number {
  return props.start + (props.end - props.start) * props.progress;
}

/** Возвращает easing-кривую с быстрым стартом и мягким окончанием. */
export function easeOutCubic(progress: number): number {
  const t = clamp({ value: progress, min: 0, max: 1 }) - 1;
  return t * t * t + 1;
}

/** Возвращает easing-кривую с легким пружинящим эффектом. */
export function easeOutBack(progress: number): number {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  const t = clamp({ value: progress, min: 0, max: 1 }) - 1;

  return 1 + c3 * t * t * t + c1 * t * t;
}

/** Генерирует случайное целое число от нуля до указанного предела. */
export function randomInt(maxExclusive: number): number {
  return Math.floor(Math.random() * maxExclusive);
}

/** Генерирует случайное число с плавающей точкой в диапазоне. */
export function randomRange(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

/** Создает квадратную матрицу и заполняет ее значениями. */
export function createMatrix<T>(size: number, valueFactory: T | ((row: number, col: number) => T)): T[][] {
  const matrix: T[][] = [];

  for (let row = 0; row < size; row += 1) {
    matrix[row] = [];

    for (let col = 0; col < size; col += 1) {
      matrix[row][col] = typeof valueFactory === "function"
        ? (valueFactory as (row: number, col: number) => T)(row, col)
        : valueFactory;
    }
  }

  return matrix;
}

/** Выбирает случайный элемент массива. */
export function pickRandom<T>(items: T[]): T | null {
  if (items.length === 0) {
    return null;
  }

  return items[randomInt(items.length)];
}

/** Безопасно читает строковое значение из localStorage. */
export function storageGet(key: string, fallback: string): string {
  try {
    const value = window.localStorage.getItem(key);
    return value === null ? fallback : value;
  } catch (error) {
    return fallback;
  }
}

/** Безопасно записывает строковое значение в localStorage. */
export function storageSet(key: string, value: string): void {
  try {
    window.localStorage.setItem(key, value);
  } catch (error) {
    return;
  }
}

/** Форматирует число с пробелами между разрядами. */
export function formatNumber(value: number): string {
  return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}
