import type { IBodyStyleSnapshot, IHtmlCrossfadeBackgroundLayer } from "./types";

interface IHtmlCrossfadeBackgroundProps extends IHtmlCrossfadeBackgroundLayer {
  durationMs?: number;
}

/** Управляет HTML-фоном страницы с плавным проявлением нового изображения поверх старого. */
export class HtmlCrossfadeBackground {
  private readonly bodyStyleSnapshot: IBodyStyleSnapshot;
  private readonly rootElement: HTMLDivElement;
  private currentLayer: HTMLDivElement;
  private currentLayerConfig: IHtmlCrossfadeBackgroundLayer;
  private nextLayer?: HTMLDivElement;
  private transitionTimeoutId?: number;
  private animationFrameId?: number;
  private readonly durationMs: number;

  /** Создает fixed background-layer и применяет стартовую картинку без анимации. */
  constructor(props: IHtmlCrossfadeBackgroundProps) {
    this.durationMs = props.durationMs ?? 1200;
    this.bodyStyleSnapshot = this.snapshotBodyStyle();
    this.rootElement = this.createRootElement();
    this.currentLayerConfig = this.normalizeLayerConfig(props);
    this.currentLayer = this.createLayer(this.currentLayerConfig, 1, false);

    this.prepareBodyStyle();
    this.rootElement.appendChild(this.currentLayer);
    document.body.appendChild(this.rootElement);
  }

  /** Плавно проявляет новый фон поверх текущего. */
  setBackground(nextLayerConfig: IHtmlCrossfadeBackgroundLayer): void {
    const normalizedConfig = this.normalizeLayerConfig(nextLayerConfig);

    if (this.isSameLayer(this.currentLayerConfig, normalizedConfig)) {
      return;
    }

    this.clearPendingTransition();
    this.nextLayer?.remove();
    this.nextLayer = this.createLayer(normalizedConfig, 0, true);
    this.rootElement.appendChild(this.nextLayer);

    this.animationFrameId = window.requestAnimationFrame(() => {
      this.animationFrameId = window.requestAnimationFrame(() => {
        if (!this.nextLayer) {
          return;
        }

        this.nextLayer.style.opacity = "1";
      });
    });

    this.transitionTimeoutId = window.setTimeout(() => {
      this.commitNextLayer(normalizedConfig);
    }, this.durationMs + 80);
  }

  /** Удаляет DOM-слои и возвращает body-style к состоянию до создания фона. */
  destroy(): void {
    this.clearPendingTransition();
    this.rootElement.remove();
    this.applyBodyStyle(this.bodyStyleSnapshot);
  }

  /** Фиксирует текущие inline-стили body, которые меняет фон. */
  private snapshotBodyStyle(): IBodyStyleSnapshot {
    const bodyStyle = document.body.style;

    return {
      background: bodyStyle.background,
      backgroundImage: bodyStyle.backgroundImage,
      backgroundSize: bodyStyle.backgroundSize,
      backgroundPosition: bodyStyle.backgroundPosition,
      backgroundRepeat: bodyStyle.backgroundRepeat,
      position: bodyStyle.position,
      zIndex: bodyStyle.zIndex,
    };
  }

  /** Подготавливает body так, чтобы fixed-слои были видны под прозрачным Phaser canvas. */
  private prepareBodyStyle(): void {
    const bodyStyle = document.body.style;

    bodyStyle.position = "relative";
    bodyStyle.zIndex = "0";
    bodyStyle.background = "transparent";
    bodyStyle.backgroundImage = "none";
    bodyStyle.backgroundSize = "";
    bodyStyle.backgroundPosition = "";
    bodyStyle.backgroundRepeat = "";
  }

  /** Возвращает body-style из сохраненного snapshot. */
  private applyBodyStyle(snapshot: IBodyStyleSnapshot): void {
    const bodyStyle = document.body.style;

    bodyStyle.background = snapshot.background;
    bodyStyle.backgroundImage = snapshot.backgroundImage;
    bodyStyle.backgroundSize = snapshot.backgroundSize;
    bodyStyle.backgroundPosition = snapshot.backgroundPosition;
    bodyStyle.backgroundRepeat = snapshot.backgroundRepeat;
    bodyStyle.position = snapshot.position;
    bodyStyle.zIndex = snapshot.zIndex;
  }

  /** Создает общий контейнер HTML-слоев ниже Phaser canvas. */
  private createRootElement(): HTMLDivElement {
    const element = document.createElement("div");

    element.style.position = "fixed";
    element.style.inset = "0";
    element.style.pointerEvents = "none";
    element.style.zIndex = "-1";
    element.style.overflow = "hidden";

    return element;
  }

  /** Создает один CSS background-layer с cover-растяжением. */
  private createLayer(
    layerConfig: IHtmlCrossfadeBackgroundLayer,
    opacity: number,
    isAnimated: boolean,
  ): HTMLDivElement {
    const element = document.createElement("div");
    const imageValue = this.createBackgroundImageValue(layerConfig);

    element.style.position = "absolute";
    element.style.inset = "0";
    element.style.pointerEvents = "none";
    element.style.backgroundImage = imageValue;
    element.style.backgroundSize = imageValue ? this.createRepeatedValue(layerConfig, "cover") : "";
    element.style.backgroundPosition = imageValue ? this.createRepeatedValue(layerConfig, "center") : "";
    element.style.backgroundRepeat = imageValue ? this.createRepeatedValue(layerConfig, "no-repeat") : "";
    element.style.opacity = String(opacity);
    element.style.transition = isAnimated ? `opacity ${this.durationMs}ms ease` : "";

    return element;
  }

  /** Делает следующий слой текущим после завершения crossfade. */
  private commitNextLayer(nextLayerConfig: IHtmlCrossfadeBackgroundLayer): void {
    if (!this.nextLayer) {
      return;
    }

    this.currentLayer.remove();
    this.currentLayer = this.nextLayer;
    this.currentLayer.style.transition = "";
    this.currentLayerConfig = nextLayerConfig;
    this.nextLayer = undefined;
    this.clearPendingTransition();
  }

  /** Отменяет незавершенную анимацию/таймер без удаления DOM-слоев. */
  private clearPendingTransition(): void {
    if (this.animationFrameId != null) {
      window.cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = undefined;
    }

    if (this.transitionTimeoutId != null) {
      window.clearTimeout(this.transitionTimeoutId);
      this.transitionTimeoutId = undefined;
    }
  }

  /** Нормализует конфиг слоя, оставляя только поля, влияющие на фон. */
  private normalizeLayerConfig(layerConfig: IHtmlCrossfadeBackgroundLayer): IHtmlCrossfadeBackgroundLayer {
    return {
      url: layerConfig.url,
      fallbackUrl: layerConfig.fallbackUrl,
      defaultUrl: layerConfig.defaultUrl,
    };
  }

  /** Сравнивает фоновые слои, чтобы не запускать лишний fade на тот же URL. */
  private isSameLayer(
    left: IHtmlCrossfadeBackgroundLayer,
    right: IHtmlCrossfadeBackgroundLayer,
  ): boolean {
    return left.url === right.url
      && left.fallbackUrl === right.fallbackUrl
      && left.defaultUrl === right.defaultUrl;
  }

  /** Собирает CSS background-image из основного, fallback и default URL. */
  private createBackgroundImageValue(layerConfig: IHtmlCrossfadeBackgroundLayer): string {
    return this.getLayerUrls(layerConfig)
      .map((url) => `url("${url}")`)
      .join(", ");
  }

  /** Повторяет одно CSS-значение под количество background-image слоев. */
  private createRepeatedValue(layerConfig: IHtmlCrossfadeBackgroundLayer, value: string): string {
    return this.getLayerUrls(layerConfig).map(() => value).join(", ");
  }

  /** Возвращает список URL, реально участвующих в CSS background-image. */
  private getLayerUrls(layerConfig: IHtmlCrossfadeBackgroundLayer): string[] {
    return [layerConfig.url, layerConfig.fallbackUrl, layerConfig.defaultUrl].filter(
      (url): url is string => url != null,
    );
  }
}
