import { SceneEvents } from "../../../../common";
import type { Observable, UnSubscriber } from "../../../../common";
import type { ICinderella2048GameState } from "../Cinderella2048Game";
import { Cinderella2048Button } from "./Cinderella2048Button";
import type { ICinderella2048UiEvents } from "./events";
import { formatCinderella2048Number } from "./utils";
import { cinderella2048ViewConfig } from "../constants";

interface ICinderella2048UiProps {
  scene: Phaser.Scene;
  gameState: Observable<ICinderella2048GameState>;
}

/** Рисует верхнюю панель счета, рекорда, ходов и кнопок. */
export class Cinderella2048Ui extends Phaser.GameObjects.Container {
  private scoreValue: Phaser.GameObjects.Text;
  private bestValue: Phaser.GameObjects.Text;
  private movesValue: Phaser.GameObjects.Text;
  private newGameButton: Cinderella2048Button;
  private undoButton: Cinderella2048Button;
  private gameState: Observable<ICinderella2048GameState>;
  private sceneEvents: SceneEvents<ICinderella2048UiEvents>;
  private stateUnSub: UnSubscriber;

  /** Создает HUD игрового компонента. */
  constructor(props: ICinderella2048UiProps) {
    super(props.scene, 0, 0);

    this.gameState = props.gameState;
    this.sceneEvents = new SceneEvents<ICinderella2048UiEvents>({ scene: props.scene, autoUnSub: this });
    this.scoreValue = this.createValueText();
    this.bestValue = this.createValueText();
    this.movesValue = this.createValueText();
    this.newGameButton = new Cinderella2048Button({
      scene: props.scene,
      text: "Новая игра",
      width: 154,
      height: 46,
      onClick: () => this.sceneEvents.emit("cinderella2048NewGameRequest"),
    });
    this.undoButton = new Cinderella2048Button({
      scene: props.scene,
      text: "Шаг назад",
      width: 146,
      height: 46,
      variant: "secondary",
      onClick: () => this.sceneEvents.emit("cinderella2048UndoRequest"),
    });

    this.add([
      this.createTitleBlock(),
      this.createScoreCard("Счет", this.scoreValue),
      this.createScoreCard("Рекорд", this.bestValue),
      this.createScoreCard("Ходы", this.movesValue),
      this.newGameButton,
      this.undoButton,
    ]);
    this.setDepth(cinderella2048ViewConfig.depth.hud);
    props.scene.add.existing(this);
    this.stateUnSub = this.gameState.on((state) => this.updateValues(state));
    this.updateValues(this.gameState.getState());
    this.layout();
  }

  /** Уничтожает UI и снимает подписки на состояние. */
  destroy(fromScene?: boolean): void {
    this.stateUnSub();
    this.sceneEvents.unSubscribeAll();
    super.destroy(fromScene);
  }

  /** Обновляет числовые значения и состояние кнопки отмены. */
  updateValues(props: ICinderella2048GameState): void {
    this.scoreValue.setText(formatCinderella2048Number(props.score));
    this.bestValue.setText(formatCinderella2048Number(props.best));
    this.movesValue.setText(formatCinderella2048Number(props.moves));
    this.undoButton.setEnabled(props.canUndo);
  }

  /** Обновляет позиции HUD под текущий размер сцены. */
  layout(): void {
    const width = this.scene.scale.width;
    const left = Math.max(24, (width - 900) / 2);
    const cardWidth = width < 760 ? 114 : 132;
    const cardGap = 10;
    const cardsY = width < 760 ? 82 : 46;
    const titleBlock = this.getAt(0) as Phaser.GameObjects.Container;

    titleBlock.setPosition(left, 26);

    for (let index = 0; index < 3; index += 1) {
      const card = this.getAt(index + 1) as Phaser.GameObjects.Container;
      card.setPosition(left + index * (cardWidth + cardGap), cardsY);
      card.setScale(cardWidth / 132, 1);
    }

    this.newGameButton.setPosition(width - left - 236, width < 760 ? 114 : 50);
    this.undoButton.setPosition(width - left - 70, width < 760 ? 114 : 50);
  }

  /** Создает заголовочный блок компонента. */
  private createTitleBlock(): Phaser.GameObjects.Container {
    const container = this.scene.add.container(0, 0);
    const eyebrow = this.scene.add.text(0, 0, "HTML5 Canvas · 2048", {
      fontFamily: cinderella2048ViewConfig.fontFamily,
      fontSize: "13px",
      fontStyle: "800",
      color: cinderella2048ViewConfig.colors.gold,
    });
    const title = this.scene.add.text(0, 18, "Золушка 2048", {
      fontFamily: cinderella2048ViewConfig.fontFamily,
      fontSize: "40px",
      fontStyle: "900",
      color: cinderella2048ViewConfig.colors.text,
    });

    container.add([eyebrow, title]);
    return container;
  }

  /** Создает карточку одного счетчика. */
  private createScoreCard(label: string, valueText: Phaser.GameObjects.Text): Phaser.GameObjects.Container {
    const container = this.scene.add.container(0, 0);
    const background = this.scene.add.graphics();
    const labelText = this.scene.add.text(-48, -20, label, {
      fontFamily: cinderella2048ViewConfig.fontFamily,
      fontSize: "12px",
      fontStyle: "800",
      color: cinderella2048ViewConfig.colors.muted,
    });

    background.fillStyle(0xffffff, 0.08);
    background.fillRoundedRect(-66, -34, 132, 68, 16);
    background.lineStyle(1, 0xffffff, 0.13);
    background.strokeRoundedRect(-66, -34, 132, 68, 16);
    valueText.setPosition(-48, 3);
    container.add([background, labelText, valueText]);

    return container;
  }

  /** Создает текстовое поле значения счетчика. */
  private createValueText(): Phaser.GameObjects.Text {
    return this.scene.add.text(0, 0, "0", {
      fontFamily: cinderella2048ViewConfig.fontFamily,
      fontSize: "26px",
      fontStyle: "900",
      color: cinderella2048ViewConfig.colors.text,
    });
  }
}
